use super::*;
#[derive(Deserialize)]
#[serde(rename_all="camelCase")]
pub struct Edit {positions:Vec<V>,faces:Vec<[usize;3]>,operation:String,#[serde(default)]vertices:Vec<usize>,#[serde(default)]edges:Vec<[usize;2]>,#[serde(default)]selected_faces:Vec<usize>,#[serde(default)]distance:f64,#[serde(default)]matrix:Option<[f64;16]>,#[serde(default)]weld_classes:Vec<String>}
pub fn run(q:Edit)->Result<serde_json::Value,String>{
 topology(&Mesh{positions:q.positions.clone(),faces:q.faces.clone()})?;
 let mut p=q.positions;let mut f=q.faces;let mut sources:Vec<Vec<(usize,f64)>>=(0..p.len()).map(|i|vec![(i,1.)]).collect();let mut fs:Vec<usize>=(0..f.len()).collect();
 if q.vertices.iter().any(|&v|v>=p.len())||q.edges.iter().flatten().any(|&v|v>=p.len())||q.selected_faces.iter().any(|&v|v>=f.len())||!q.distance.is_finite(){return Err("Invalid component selection".into())}
 let selected:HashSet<_>=q.vertices.iter().copied().collect();let selected_faces:HashSet<_>=q.selected_faces.iter().copied().collect();
 match q.operation.as_str(){
 "transform"=>{let m=q.matrix.ok_or("Transform matrix is missing")?;if !m.iter().all(|v|v.is_finite())||m[3]!=0.||m[7]!=0.||m[11]!=0.||m[15]!=1.{return Err("Invalid affine matrix".into())}for &i in &selected{let v=p[i];p[i]=[m[0]*v[0]+m[4]*v[1]+m[8]*v[2]+m[12],m[1]*v[0]+m[5]*v[1]+m[9]*v[2]+m[13],m[2]*v[0]+m[6]*v[1]+m[10]*v[2]+m[14]];}}
 "delete"=>{let mut nf=Vec::new();let mut ns=Vec::new();for (i,t) in f.iter().enumerate(){if selected_faces.contains(&i)||t.iter().any(|v|selected.contains(v))||q.edges.iter().any(|e|t.contains(&e[0])&&t.contains(&e[1])){continue}nf.push(*t);ns.push(fs[i]);}f=nf;fs=ns;}
 "split"=>{if q.edges.len()>10000{return Err("Split selection exceeds 10000 edges".into())}for e in q.edges{let mut found=false;let mid=p.len();let mut nf=Vec::new();let mut ns=Vec::new();for (i,t) in f.iter().enumerate(){let edge=(0..3).find(|&j|(t[j]==e[0]&&t[(j+1)%3]==e[1])||(t[j]==e[1]&&t[(j+1)%3]==e[0]));if let Some(j)=edge{found=true;nf.extend([[t[j],mid,t[(j+2)%3]],[mid,t[(j+1)%3],t[(j+2)%3]]]);ns.extend([fs[i],fs[i]]);}else{nf.push(*t);ns.push(fs[i]);}}if found{p.push(mul(add(p[e[0]],p[e[1]]),0.5));let mut s=sources[e[0]].iter().chain(sources[e[1]].iter()).map(|&(i,w)|(i,w*0.5)).collect::<Vec<_>>();s.sort_by_key(|s|s.0);sources.push(s);f=nf;fs=ns;}}}
 "merge"=>{if q.distance<=0.||q.distance>1.||q.weld_classes.len()!=p.len(){return Err("Merge requires a tolerance and attribute classes".into())}let mut hash:HashMap<[i32;3],Vec<usize>>=HashMap::new();let mut remap:Vec<_>=(0..p.len()).collect();for i in 0..p.len(){if !selected.contains(&i){continue}let k=p[i].map(|v|(v/q.distance).floor() as i32);let mut best=None;for x in -1..=1{for y in -1..=1{for z in -1..=1{if let Some(list)=hash.get(&[k[0]+x,k[1]+y,k[2]+z]){for &j in list{if q.weld_classes[i]==q.weld_classes[j]&&norm(sub(p[i],p[j]))<=q.distance{best=Some(best.map_or(j,|v:usize|v.min(j)));}}}}}}if let Some(j)=best{remap[i]=j;}else{hash.entry(k).or_default().push(i);}}let mut nf=Vec::new();let mut ns=Vec::new();let mut seen=HashSet::new();for (i,t) in f.iter().enumerate(){let t=t.map(|v|remap[v]);let mut key=t;key.sort();if t[0]!=t[1]&&t[1]!=t[2]&&t[0]!=t[2]&&seen.insert(key){nf.push(t);ns.push(fs[i]);}}f=nf;fs=ns;}
 "extrude"=>{if q.distance.abs()>100.||selected_faces.is_empty(){return Err("Select faces and a bounded extrusion distance".into())}let mut normals:BTreeMap<usize,V>=BTreeMap::new();let mut boundary:BTreeMap<(usize,usize),(usize,usize,usize,usize)>=BTreeMap::new();for &i in &q.selected_faces{let t=f[i];let n=cross(sub(p[t[1]],p[t[0]]),sub(p[t[2]],p[t[0]]));for &v in &t{let a=normals.entry(v).or_insert([0.;3]);*a=add(*a,n);}for j in 0..3{let a=t[j];let b=t[(j+1)%3];let e=boundary.entry((a.min(b),a.max(b))).or_insert((a,b,0,fs[i]));e.2+=1;}}let mut remap=HashMap::new();for (&v,n) in &normals{let len=norm(*n);if len<1e-12{return Err("Extrusion has cancelling normals".into())}remap.insert(v,p.len());p.push(add(p[v],mul(*n,q.distance/len)));sources.push(sources[v].clone());}for &i in &q.selected_faces{f[i]=f[i].map(|v|remap[&v]);}for (_, (a,b,count,src)) in boundary{if count==1{f.extend([[a,b,remap[&b]],[a,remap[&b],remap[&a]]]);fs.extend([src,src]);}}}
 "dissolve"=>{ // Remove a valence-three interior vertex and restore its surrounding face.
  for &v in &q.vertices{let adjacent:Vec<_>=f.iter().enumerate().filter(|(_,t)|t.contains(&v)).map(|(i,_)|i).collect();if adjacent.len()!=3{return Err("Dissolve currently requires an interior vertex with three incident faces".into())}let mut boundary=Vec::new();for &i in &adjacent{let t=f[i];let j=t.iter().position(|&x|x==v).unwrap();boundary.push((t[(j+1)%3],t[(j+2)%3]));}let a=boundary[0].0;let b=boundary[0].1;let c=boundary.iter().find(|&&(x,_)|x==b).ok_or("Dissolve boundary is not a simple ring")?.1;if !boundary.contains(&(c,a)){return Err("Invalid dissolve boundary".into())}let n=cross(sub(p[b],p[a]),sub(p[c],p[a]));if norm(n)<1e-12||dot(sub(p[v],p[a]),n).abs()/norm(n)>1e-6{return Err("Dissolve requires a planar neighborhood".into())}let source=fs[adjacent[0]];let mut nf=Vec::new();let mut ns=Vec::new();for (i,t) in f.iter().enumerate(){if !adjacent.contains(&i){nf.push(*t);ns.push(fs[i]);}}nf.push([a,b,c]);ns.push(source);f=nf;fs=ns;}
 }
 _=>return Err("Unknown component operation".into())
 }
 if f.is_empty(){return Err("Operation would remove the entire mesh; delete the object instead".into())}
 let mut used=vec![false;p.len()];for t in &f{for &v in t{used[v]=true;}}let mut remap=vec![0;p.len()];let mut out=Vec::new();let mut weights=Vec::new();for i in 0..p.len(){if used[i]{remap[i]=out.len();out.push(p[i]);weights.push(sources[i].clone());}}for t in &mut f{*t=t.map(|v|remap[v]);}
 let topo=topology(&Mesh{positions:out.clone(),faces:f.clone()})?;
 Ok(serde_json::json!({"positions":out,"faces":f,"vertexSources":weights,"faceSources":fs,"topology":topo}))
}
